    def _build_index(self):
        index = {}
        for i, (fact_id, text, keywords) in enumerate(self.facts):
            for kw in keywords:
                kw_lower = kw.lower()
                if kw_lower not in index:
                    index[kw_lower] = []
                if i not in index[kw_lower]:
                    index[kw_lower].append(i)
            words = set(re.findall(r'[a-zéèêëàâîïôûùçœæ\d]+', text.lower()))
            for w in words:
                if w not in index:
                    index[w] = []
                if i not in index[w]:
                    index[w].append(i)
        return index

    def lookup(self, prompt: str) -> Tuple[Optional[str], float]:
        p = prompt.lower().strip()
        words = set(re.findall(r'[a-zéèêëàâîïôûùçœæ\d]+', p))
        fact_scores = {}

        for i, (_, _, keywords) in enumerate(self.facts):
            for kw in keywords:
                kw_lower = kw.lower()
                if ' ' in kw_lower and kw_lower in p:
                    fact_scores[i] = fact_scores.get(i, 0) + 10.0

        for word in words:
            if word in self._word_index:
                for fact_idx in self._word_index[word]:
                    _, _, keywords = self.facts[fact_idx]
                    is_keyword = word in [k.lower() for k in keywords]
                    weight = 3.0 if is_keyword else 1.0
                    fact_scores[fact_idx] = fact_scores.get(fact_idx, 0) + weight

        if not fact_scores:
            return None, 0.0

        best_idx = max(fact_scores, key=lambda x: (fact_scores[x], -x))
        best_score = fact_scores[best_idx]
        _, text, keywords = self.facts[best_idx]

        keyword_match = any(kw.lower() in p for kw in keywords)
        if not keyword_match and best_score < 3:
            return None, 0.0

        confidence = min(1.0, best_score / max(len(words), 1) + 0.3)
        return text, confidence

    def get_all_facts_count(self) -> int:
        return len(self.facts)

